/** The tags of a post as small badges in a wrapping row. */
import { For, type JSX } from "solid-js";
import { Badge } from "../primitives/badge/badge";
import { Group } from "../primitives/group/group";
import type { NavLink } from "../blocks/nav-bar.types";

export type PostTagsProps = {
  tags: NavLink[];
  align?: "start" | "center";
};

export function PostTags({ tags, align = "start" }: PostTagsProps) {
  return (
    <Group gap="2" justify={align} class="flex-wrap">
      <For each={tags ?? []}>{(tag) => (
        <Badge variant="secondary" size="sm" data-testid="post-tag">
          {tag.name}
        </Badge>
      )}</For>
    </Group>
  );
}
